//! 🧪️ A native Pack receiver preserves actual source custody and physically settles before handoff.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,default_now_us};
use semio_framework_value::{RetainedCloneGrant,retirement::controlled::ControlledRetirement};
fn turn<R>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->R{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"actual original Pack receipt {p:?}");result.unwrap()}
#[test]
fn original_pack_typed_receiving_settles_every_original_before_unique_handoff(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let text=law["text"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize);let oracle:serde_json::Value=serde_json::from_str(&serde_json::to_string(&text).unwrap()).unwrap();
 for cut in law["cancelPrefixes"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([None]){
  let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096};let mut caller=OriginalJobFixtureCaller::admit(OperationId(381),Generation(7),RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<29,maximum_release_bytes:1<<29,maximum_depth:4096},default_now_us,u64::MAX,1<<30);let mut decoder=OriginalJobDecodeOwner::empty();
  let mut allow=|_|true;let mut encode=semio_framework_value::NativeEncodeControl::new(1<<24,&mut allow);let mut raw=semio_framework_pack_record::intrinsic::encode_body(&DslValue::String(text.clone()),&Default::default(),&mut encode).unwrap();let pointer=raw.as_ptr();let length=raw.len();let mut owner=None;let d=RetirementDemand{capacity_bytes:size_of::<OriginalPackReceiving<String>>(),..fixed::<OriginalPackReceiving<String>>()};
  for axis in 0..4{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,2=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3=>denied.maximum_depth=0,_=>unreachable!()}turn(&mut caller,&mut decoder,denied,|cx|{assert!(!OriginalPackReceiving::<String>::admit(&mut raw,Default::default(),cx,&mut owner)?);Ok(())});assert!(owner.is_none());assert_eq!((raw.as_ptr(),raw.len()),(pointer,length));}
  turn(&mut caller,&mut decoder,g,|cx|{assert!(OriginalPackReceiving::<String>::admit(&mut raw,Default::default(),cx,&mut owner)?);Ok(())});assert!(raw.is_empty());assert_eq!(owner.as_ref().unwrap().parser.as_ref().unwrap().input().unwrap().as_ptr(),pointer);
  for index in 0..262144{if cut==Some(index){break}let ready=turn(&mut caller,&mut decoder,g,|cx|owner.as_mut().unwrap().advance(cx));if ready{break}assert!(index<262143,"original Pack receiving did not settle");}
  let mut output=None;if cut.is_none(){turn(&mut caller,&mut decoder,g,|cx|{assert!(owner.as_mut().unwrap().take(cx,&mut output)?);Ok(())});assert_eq!(serde_json::Value::String(output.as_ref().unwrap().clone()),oracle);}else{caller.cancel().cancel_now();}
  for index in 0..262144{if owner.as_ref().unwrap().terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close_step(cx)));assert!(index<262143,"original Pack cancellation did not settle");}
  turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=OriginalPackReceiving::<String>::release_demands();close_original_retained_step(cx,d,|_|{owner.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(())}));
  while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
  if let Some(output)=output{let mut close=ControlledRetirement::new(output).map_err(|(error,_)|error).unwrap();for index in 0..262144{if close.terminal_is_empty(){break}let selection=close.select(4096).unwrap();let d=selection.demands();let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||selection.step(exact).unwrap());assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),(heap.requested_bytes,heap.released_bytes));assert!(index<262143);}}
 }
}

fn receive_authored<T:NativeReceive<DslValue>+Sync+semio_framework_value::ToValue+PartialEq+std::fmt::Debug>(value:T){
 use semio_framework_value::ToValue;
 let input=value.to_value();let mut allow=|_|true;let mut encode=semio_framework_value::NativeEncodeControl::new(1<<24,&mut allow);let mut raw=semio_framework_pack_record::intrinsic::encode_body(&input,&Default::default(),&mut encode).unwrap();let mut caller=OriginalJobFixtureCaller::admit(OperationId(383),Generation(9),RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<29,maximum_release_bytes:1<<29,maximum_depth:4096},default_now_us,u64::MAX,1<<30);let mut decoder=OriginalJobDecodeOwner::empty();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096};let mut owner=None;turn(&mut caller,&mut decoder,g,|cx|{assert!(OriginalPackReceiving::<T>::admit(&mut raw,Default::default(),cx,&mut owner)?);Ok(())});for index in 0..262144{if turn(&mut caller,&mut decoder,g,|cx|owner.as_mut().unwrap().advance(cx)){break}assert!(index<262143,"authored typed transaction field stalled");}let mut output=None;turn(&mut caller,&mut decoder,g,|cx|{assert!(owner.as_mut().unwrap().take(cx,&mut output)?);Ok(())});assert_eq!(output.as_ref().unwrap(),&value);assert_eq!(output.as_ref().unwrap().to_value(),input);
 for index in 0..262144{if owner.as_ref().unwrap().terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close_step(cx)));assert!(index<262143);}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=OriginalPackReceiving::<T>::release_demands();close_original_retained_step(cx,d,|_|{owner.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(())}));let mut close=RetainedCloneClose::default();for index in 0..262144{if output.is_none()&&close.is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=close.next_owner_demands::<T>(output.is_some(),&None,4096)?;close_original_retained_step(cx,d,|grant|if close.is_empty(){Ok(close.begin_granted(&mut output,grant)?.unwrap_or(RetainedCloneStep::Complete(Default::default())))}else{close.select(4096)?.step(grant)})?;Ok(())}));assert!(index<262143);}while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
}
#[test]fn original_transaction_origin_and_child_groups_receive_their_authored_wire_fields(){
 use semio_framework_os_kernel as protocol;
 receive_authored(protocol::MutationOrigin::Owner);
 receive_authored(protocol::MutationOrigin::Contributed{plugin_id:"contributor λ🙂".repeat(2049),mutation_id:protocol::SchemaId("authored-operation".into()),payload_hash:protocol::PayloadHash([7;32])});
 receive_authored(protocol::MutationOrigin::Transaction{initiator:protocol::ForeignTarget{artifact_id:"original-initiator".into(),artifact_kind:"s.test.source".into(),dialect:Some("s.test.source@1#full".into())}});
 let label=semio_framework_ui_locale::LocalizedLabel::from_fn(|terminology,locale|format!("{}:{}:λ🙂",terminology.as_str(),locale.as_str()));let child=semio_framework_plugin_decl_emission::ChildEmit{genesis:Some(semio_framework_plugin_decl_emission::ChildEmitGenesis{reference:semio_framework_artifact_reference::ArtifactRef{artifact_id:"original-genesis".into(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.test.child".into(),standard:"1".into(),subset:"full".into()}},initial_pack:vec![1,2,127,255]}),owner:"parent/owner".into(),slot:"children".into(),child_id:"original-child".into(),ops:vec![vec![1,2],vec![3]],op_schema:protocol::SchemaId("s.test.child#edit".into()),labels:vec![label]};receive_authored(vec![child]);
}
